function raceFeatures(raceId, variant, fallbackDescription = "", fallbackTags = []) {
	let lines = raceText[raceId] || [fallbackDescription, ...fallbackTags.map((tag) => `${tag} — ключевая особенность выбранной расы.`)];
	if (raceId === "human") lines = variant === "variant" ? [lines[1], lines[2]] : [lines[0], lines[2]];
	return lines.filter(Boolean).map((line) => {
		const [name, ...rest] = line.split(" — ");
		return {
			name,
			description: rest.join(" — ") || line
		};
	});
}
