function download(payload, name) {
	const url = URL.createObjectURL(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }));
	const anchor = document.createElement("a");
	anchor.href = url;
	anchor.download = name;
	anchor.click();
	URL.revokeObjectURL(url);
}
function safeName(value) {
	return (value || "герой").replace(/[\\/:*?"<>|]+/g, "-").trim();
}
function slotId() {
	return `hero-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}
function createSlot(character = initial) {
	return {
		id: slotId(),
		character,
		updatedAt: (/* @__PURE__ */ new Date()).toISOString()
	};
}
function allowed(list, category, id) {
	if (!list) return true;
	const hit = list.categories[category]?.includes(id);
	return list.mode === "deny" ? !hit : !!hit;
}
function levelLabel(value) {
	return value === 0 ? "Заговор" : `${value} круг`;
}
function hasOriginFeat(character) {
	return character.race === "human" && character.raceVariant === "variant" || character.race === "customlineage";
}
function advancementSlotsFor(character) {
	return [...hasOriginFeat(character) ? [{
		key: "origin-1",
		level: 1,
		origin: true
	}] : [], ...asiLevelsForClass(character.className).filter((level) => level <= character.level).map((level) => ({
		key: `class-${level}`,
		level,
		origin: false
	}))];
}
function deriveLegacyAdvancementFields(advancements) {
	return {
		feats: advancements.map((choice) => choice.featId).filter(Boolean),
		asiChoices: advancements.flatMap((choice) => choice.featId === "asi" ? choice.asiChoices : [])
	};
}
function syncAdvancements(character, advancements) {
	return {
		...character,
		advancements,
		...deriveLegacyAdvancementFields(advancements)
	};
}
